#pragma once
// Included after the CPU fixture declarations; no production visibility hacks.
inline void RunCPUExtra(Suite& t){
    t.Test("T01 rejects duplicate properties incomplete SH and inactive nonfinite coefficients",[]{Context c("ply-extra");auto p=PLY(c,1);auto b=Read(p);std::string text(b.begin(),b.end());auto start=text.find("property float f_rest_8\n");Require(start!=std::string::npos,"fixture SH field");text.erase(start,std::string("property float f_rest_8\n").size());Write(c.dir/"partial.ply",{text.begin(),text.end()});std::vector<FSplatGaussian> out;unsigned degree=0;std::string e;Require(!FSplatPLYLoader::LoadCPU((c.dir/"partial.ply").string(),out,degree,e),"incomplete SH accepted");text.assign(b.begin(),b.end());text.insert(text.find("end_header"),"property float x\n");Write(c.dir/"duplicate.ply",{text.begin(),text.end()});Require(!FSplatPLYLoader::LoadCPU((c.dir/"duplicate.ply").string(),out,degree,e),"duplicate property accepted");auto g=Gaussian(0);g.sh[47]=std::numeric_limits<float>::quiet_NaN();std::vector<uint8_t> encoded;Require(!FSplatSceneFormat::EncodePage({g},3,encoded,e),"nonfinite SH serialized");});
    t.Test("T03 rotated anisotropic support remains conservative",[]{Context c("rotated-support");auto g=Gaussian(0);g.scale[0]=4;g.scale[1]=g.scale[2]=1;g.rotation[0]=float(std::cos(3.141592653589793/8));g.rotation[3]=float(std::sin(3.141592653589793/8));auto m=Build(c,{g});const double radius=3*std::sqrt(8.5);for(unsigned k=0;k<2;++k)Require(m.nodes[0].bounds.min[k]<=g.position[k]-radius+1e-5&&m.nodes[0].bounds.max[k]>=g.position[k]+radius-1e-5,"rotated covariance support omitted");});
    t.Test("T07 missing ancestor never publishes partial visible descendant coverage",[]{auto m=SmallTree();auto r=Ready(m);r.pages[0].ready=r.pages[1].ready=r.pages[3].ready=false;FSplatLODSelector selector;auto cut=selector.Select(m,View(),Settings(),r);Require(cut.selectedNodeIds.empty()&&cut.degraded,"partial resident branch exposed as complete cut");Require(cut.requestPageIds==std::vector<uint32_t>({0,1}),"complete ancestor refill missing");});
    t.Test("T06 broad support estimate does not veto complete refinement but zero hard sort budget fails",[]{auto m=SmallTree();auto r=Ready(m);auto settings=Settings();settings.sortBudget=1;FSplatLODSelector selector;Require(selector.Select(m,View(),settings,r).selectedNodeIds==std::vector<uint32_t>({1,2}),"loose bounds estimate still gates actual GPU count");settings.sortBudget=0;auto cut=selector.Select(m,View(),settings,r);Require(cut.selectedNodeIds.empty()&&cut.degraded,"zero actual sort capacity accepted");});
    t.Test("T08 priority and metadata saturation are bounded admission failures not terminal I/O",[]{Context c("saturation");auto cfg=Config();cfg.maxDepth=0;cfg.maxPageGaussians=1;std::vector<FSplatGaussian> g;for(unsigned i=0;i<8;++i)g.push_back(Gaussian(i));auto m=Build(c,g,cfg);FSplatStreamingConfig config;config.cpuCacheBytes=4096;config.maxConcurrentReads=1;FSplatPageStreamer streamer;std::string e;Require(streamer.Open(m,(c.dir/"scene").string(),config,e),e);std::atomic<uint32_t> first{SplatInvalidId};streamer.SetFaultInjector([&](unsigned id,unsigned){auto previous=SplatInvalidId;first.compare_exchange_strong(previous,id);return FSplatPageReadFault{};});std::vector<FSplatPageRequest> requests={{0,100,1}};for(unsigned i=1;i<8;++i)requests.push_back({i,1,1});streamer.Request(requests);auto out=Wait(streamer);Require(first==0&&out[0].pageId==0&&out[0].error.empty(),"highest admitted priority failed progress");Require(streamer.GetStats().failed>0,"metadata saturation not observable");Require(streamer.GetMemoryStats().peakReservedBytes<=config.cpuCacheBytes&&streamer.GetMemoryStats().terminalFailurePages==0,"admission failure corrupted terminal history/budget");Release(streamer,out[0]);streamer.Shutdown();Require(streamer.GetMemoryStats().totalReservedBytes==0,"saturated shutdown accounting leak");});
    t.Test("T08 LRU encoded eviction permits verified reread without growth",[]{Context c("cache-evict");auto cfg=Config();cfg.maxDepth=0;cfg.maxPageGaussians=1;auto m=Build(c,{Gaussian(0),Gaussian(1)},cfg);FSplatStreamingConfig config;config.cpuCacheBytes=2000;config.maxConcurrentReads=1;FSplatPageStreamer streamer;std::string e;Require(streamer.Open(m,(c.dir/"scene").string(),config,e),e);for(unsigned id:{0u,1u,0u}){streamer.Request({{id,1,1}});auto out=Wait(streamer);Require(out[0].error.empty()&&out[0].decodedGaussians[0].originalId==id,"eviction/reread wrong payload");Release(streamer,out[0]);}Require(streamer.GetStats().bytesRead==2*m.pages[0].byteSize+m.pages[1].byteSize,"evicted page not genuinely reread");Require(streamer.GetMemoryStats().peakReservedBytes<=config.cpuCacheBytes,"cache eviction exceeded cap");streamer.Shutdown();});
}
